<?php $title='Detalhes do cliente'; ?>
<section class="page-head"><div><h1><?= e($client['name']) ?></h1><p><?= e($client['identifier']) ?></p></div><div><a class="btn" href="<?= e(base_url('clientes/'.$client['id'].'/projetos')) ?>">Gerenciar projetos</a> <a class="btn primary" href="<?= e(base_url('clientes/'.$client['id'].'/editar')) ?>">Editar</a></div></section>
<div class="detail-grid"><section class="panel"><h2>Dados cadastrais</h2><dl><dt>Status</dt><dd><span class="badge <?= e($client['status']) ?>"><?= $client['status']==='active'?'Ativo':'Inativo' ?></span></dd><dt>Administradora</dt><dd><?= e($client['administrator_name']) ?></dd><dt>E-mail</dt><dd><?= e($client['email']) ?></dd><dt>Telefone</dt><dd><?= e($client['phone']?:'Não informado') ?></dd><dt>Cadastrado em</dt><dd><?= e(date('d/m/Y H:i',strtotime($client['created_at']))) ?></dd><dt>Última atualização</dt><dd><?= e(date('d/m/Y H:i',strtotime($client['updated_at']))) ?></dd><dt>Observações</dt><dd><?= nl2br(e($client['notes']?:'Nenhuma observação.')) ?></dd></dl></section>
<section class="panel"><h2>Projetos liberados</h2><?php if(!$projects): ?><div class="empty">Nenhum projeto liberado.</div><?php else: ?><div class="project-list"><?php foreach($projects as $p): ?><a href="<?= e(base_url('projetos/'.$p['id'])) ?>"><b><?= e($p['name']) ?></b><small>v<?= e($p['version']) ?> • liberado em <?= e(date('d/m/Y',strtotime($p['activated_at']))) ?></small></a><?php endforeach; ?></div><?php endif; ?></section></div>

